package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonStringFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.BeanProperty;
import com.fasterxml.jackson.databind.ser.BeanSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.JsonSerializer;
import com.fasterxml.jackson.databind.ser.std.TypeSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.LinkedHashSet;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class JsonValueSerializer_serializeWithType_TriageGen1Test {

    private JsonValueSerializer serializer;

    @Mock
    private JsonGenerator gen;

    @Mock
    private SerializerProvider provider;

    @Mock
    private TypeSerializer typeSer0;

    @Mock
    private BeanProperty property;

    @Mock
    private JsonSerializer<Object> valueSerializer;

    @Mock
    private com.fasterxml.jackson.databind.ser.PropertyAccessor accessorMethod;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // We use a subclass or reflection to set private fields because the class 
        // structure implies internal state management for _accessorMethod, _valueSerializer, etc.
        serializer = spy(new JsonValueSerializer());

        // Injecting private fields via reflection to simulate the internal state
        setField(serializer, "_accessorMethod", accessorMethod);
        setField(serializer, "_valueSerializer", null);
        setField(serializer, "_property", property);
        setField(serializer, "_forceTypeInformation", false);
    }

    private void setField(Object target, String name, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testSerializeWithType_NullValue() throws Exception {
        Object bean = new Object();
        when(accessorMethod.getValue(bean)).thenReturn(null);

        serializer.serializeWithType(bean, gen, provider, typeSer0);

        verify(provider).defaultSerializeNull(gen);
        verifyNoInteractions(typeSer0);
    }

    @Test
    public void testSerializeWithType_FetchSerializerWhenNull() throws Exception {
        Object bean = new Object();
        Object value = "testValue";
        when(accessorMethod.getValue(bean)).thenReturn(value);
        when(provider.findValueSerializer(eq(value.getClass()), eq(property))).thenReturn(valueSerializer);

        serializer.serializeWithType(bean, gen, provider, typeSer0);

        verify(valueSerializer).serializeWithType(eq(value), eq(gen), eq(provider), eq(typeSer0));
    }

    @Test
    public void testSerializeWithType_ForceTypeInformation() throws Exception {
        Object bean = new Object();
        Object value = "testValue";
        setField(serializer, "_valueSerializer", valueSerializer);
        setField(serializer, "_forceTypeInformation", true);
        when(accessorMethod.getValue(bean)).thenReturn(value);

        serializer.serializeWithType(bean, gen, provider, typeSer0);

        verify(typeSer0).writeTypePrefixForScalar(bean, gen);
        verify(valueSerializer).serialize(value, gen, provider);
        verify(typeSer0).writeTypeSuffixForScalar(bean, gen);
        verify(valueSerializer, never()).serializeWithType(any(), any(), any(), any());
    }

    @Test
    public void testSerializeWithType_StandardPath() throws Exception {
        Object bean = new Object();
        Object value = "testValue";
        setField(serializer, "_valueSerializer", valueSerializer);
        setField(serializer, "_forceTypeInformation", false);
        when(accessorMethod.getValue(bean)).thenReturn(value);

        serializer.serializeWithType(bean, gen, provider, typeSer0);

        verify(valueSerializer).serializeWithType(value, gen, provider, typeSer0);
    }

    @Test
    public void testSerializeWithType_IOException() throws Exception {
        Object bean = new Object();
        when(accessorMethod.getValue(bean)).thenThrow(new IOException("IO Error"));

        try {
            serializer.serializeWithType(bean, gen, provider, typeSer0);
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testSerializeWithType_ExceptionWrapping() throws Exception {
        Object bean = new Object();
        when(accessorMethod.getValue(bean)).thenThrow(new RuntimeException("Runtime Error"));
        when(accessorMethod.getName()).thenReturn("getValue");

        try {
            serializer.serializeWithType(bean, gen, provider, typeSer0);
        } catch (JsonMappingException e) {
            // Expected
        }
    }

    @Test
    public void testSerializeWithType_UnwrapInvocationTargetException() throws Exception {
        Object bean = new Object();
        RuntimeException cause = new RuntimeException("The real cause");
        java.lang.reflect.InvocationTargetException ite = new java.lang.reflect.InvocationTargetException(cause);

        // Mocking the accessor to throw the wrapped exception
        when(accessorMethod.getValue(bean)).thenThrow(ite);
        when(accessorMethod.getName()).thenReturn("getValue");

        try {
            serializer.serializeWithType(bean, gen, provider, typeSer0);
        } catch (JsonMappingException e) {
            // Verify the cause is unwrapped
            assert e.getCause().equals(cause);
        }
    }

    @Test
    public void testSerializeWithType_ErrorPropagation() throws Exception {
        Object bean = new Object();
        OutOfMemoryError error = new OutOfMemoryError("OOM");
        when(accessorMethod.getValue(bean)).thenThrow(error);

        try {
            serializer.serializeWithType(bean, gen, provider, typeSer0);
        } catch (OutOfMemoryError e) {
            // Should propagate the Error directly
        }
    }
}
